<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_login();
$rows=db()->query("SELECT p.id,p.code,p.status,p.product_type,p.batch_ref,p.created_at,p.activated_at,c.name company_name,r.name reseller_name,pr.name project_name,(SELECT COUNT(*) FROM scans s WHERE s.plaque_id=p.id) scans FROM plaques p LEFT JOIN companies c ON c.id=p.company_id LEFT JOIN reseller_accounts r ON r.id=p.reseller_id LEFT JOIN projects pr ON pr.id=p.project_id ORDER BY p.id DESC LIMIT 1000")->fetchAll();
layout_start('Placas geradas');
?><div class="heading"><div><h1>Placas geradas</h1><p>Inventário completo de unidades, lotes, clientes e revendedores.</p></div><a class="button" href="plaque-batch.php">＋ Gerar lote</a></div><section class="panel"><div class="tablewrap"><table><thead><tr><th>Código</th><th>Lote</th><th>Arte original</th><th>Produto</th><th>Cliente</th><th>Revendedor</th><th>Projeto</th><th>Leituras</th><th>Status</th><th>Link</th><th>Imprimir</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['code'])?></b></td><td><?=e($r['batch_ref']??'—')?></td><td><?php $art = ['google_review'=>'assets/avaliacao_google.jpeg','whatsapp'=>'assets/placa whatsapp.png','instagram'=>'assets/placa instagram.png'][$r['product_type'] ?? ''] ?? 'assets/avaliacao_google.jpeg'; ?><img src="<?=e(app_url($art))?>" alt="Arte original da placa" style="display:block;width:64px;height:64px;object-fit:cover;border-radius:8px;border:1px solid #e1e8f0"></td><td><?=e($r['product_type'])?></td><td><?=e($r['company_name']??'—')?></td><td><?=e($r['reseller_name']??'—')?></td><td><?=e($r['project_name']??'—')?></td><td><?=$r['scans']?></td><td><?=e($r['status'])?></td><td><a target="_blank" href="<?=e(app_url('r/'.$r['code']))?>">Abrir</a></td><td><a target="_blank" href="plaque-print.php?ids=<?=$r['id']?>">Imprimir</a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="11">Nenhuma placa gerada.</td></tr><?php endif;?></tbody></table></div></section><?php layout_end();?>